#ifndef GPSPOSITION_HEADER
#define GPSPOSITION_HEADER

/* GpsPosition (0x0FB): latitude and longitude from the same GPS fix in one
 * frame. See dbc/Telemetry.dbc for the signal definitions.
 *
 * Defined here rather than in the CANApi submodule (src/CANApi, generated by
 * CANTranslator) because the board only sends this message to the radio and SD
 * card; it is never received from the CAN bus, so it needs no processMessage()
 * dispatch. Written in the same form as the generated messages so it can move
 * into CANApi at the next regeneration: once CANApi defines it (and UseMsgList
 * enables it), the guard below skips this copy.
 */
#include "src/CANApi/CANHelper.hpp"

#ifndef USE_MSG_Telemetry_GpsPosition
#define CAN_ID_Telemetry_GpsPosition 0x0FB
#define CAN_DLC_Telemetry_GpsPosition 8
namespace CANHelper::Messages
{
	namespace Telemetry
	{
		struct _GpsPosition : public Messages::CANMsg {
			struct canData {
				int32_t GpsLatitudeDeg;  // degrees x 1e7, positive north
				int32_t GpsLongitudeDeg; // degrees x 1e7, positive east
			} __attribute__((aligned(8)));
			canData data;
			_GpsPosition() : CANMsg(CAN_ID_Telemetry_GpsPosition, CAN_DLC_Telemetry_GpsPosition) { }
		};
		static_assert(sizeof(_GpsPosition::canData) == CAN_DLC_Telemetry_GpsPosition,
		              "GpsPosition payload must be exactly 8 bytes");
	}
}
#endif

#endif
